// ledGlyphRows is the fixed row count of every LEDGlyphs bitmap; a glyph's
// pixel width is len(bits) / ledGlyphRows.
const ledGlyphRows = 8

// FontLED is the variable-width LED font. It is stateless, so a zero value is
// usable. Unlike Font3x5, its TextWidth measures a string, since glyph
// widths vary.
type FontLED struct{}

func (FontLED) glyphWidth(r rune) int {
	bits, ok := LEDGlyphs[r]
	if !ok {
		return 0
	}
	return len(bits) / ledGlyphRows
}

// GlyphWidth is r's rendered width at scale (0 for a rune with no glyph).
func (f FontLED) GlyphWidth(r rune, scale int) int {
	if scale <= 0 {
		scale = 1
	}
	return f.glyphWidth(r) * scale
}

// Height is one line's pixel height at scale.
func (FontLED) Height(scale int) int {
	if scale <= 0 {
		scale = 1
	}
	return ledGlyphRows * scale
}

// TextWidth is DrawText's rendered width for s at scale. Each glyph carries
// its inter-character gap in trailing blank columns, so the width is a plain
// sum of glyph widths; a rune with no glyph adds nothing.
func (f FontLED) TextWidth(s string, scale int) int {
	if scale <= 0 {
		scale = 1
	}
	w := 0
	for _, r := range s {
		w += f.glyphWidth(r)
	}
	return w * scale
}

// MeasureText is TextWidth, so FontLED satisfies LabelFont.
func (f FontLED) MeasureText(s string, scale int) int { return f.TextWidth(s, scale) }

// DrawText draws s onto cv with its top-left at (x, y), advancing the pen by
// each glyph's scaled width (see TextWidth). Runes with no glyph are skipped.
// It does not allocate.
func (f FontLED) DrawText(cv Canvas, x, y int, s string, scale int, c Color) {
	if scale <= 0 {
		scale = 1
	}
	pen := x
	for _, r := range s {
		bits, ok := LEDGlyphs[r]
		if !ok {
			continue
		}
		width := len(bits) / ledGlyphRows
		for row := 0; row < ledGlyphRows; row++ {
			for col := 0; col < width; col++ {
				if bits[width*row+col] == 0 {
					continue
				}
				for sy := 0; sy < scale; sy++ {
					for sx := 0; sx < scale; sx++ {
						cv.Blend(pen+col*scale+sx, y+row*scale+sy, c)
					}
				}
			}
		}
		pen += width * scale
	}
}
